// auth.js
const jwt = require('jsonwebtoken');

function authenticate(req, res, next) {
  const authHeader = req.headers['authorization'];
  if (!authHeader) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  // Split on a single space and take the second segment.
  // Trim to guard against 'Bearer <token> ' trailing whitespace.
  const parts = authHeader.split(' ');
  const token = parts[1] && parts[1].trim();

  // Explicit length check: an empty string after trim must be rejected.
  if (!token || token.length === 0) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  try {
    // Do NOT pass ignoreExpiration — jwt.verify() checks exp by default.
    // An expired token throws TokenExpiredError which is caught below.
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
}

module.exports = { authenticate };
